function zeroTail(numbers, base) {
  let product = BigInt(1);
  for (const value of numbers) product *= BigInt(value);
  const divisor = BigInt(base);
  let zeros = 0;
  while (product % divisor === BigInt(0)) {
    product /= divisor;
    zeros++;
  }
  return zeros;
}

function zeroTail(numbers, base) {
  let remaining = base;
  let answer = Infinity;
  for (let prime = 2; remaining > 1; prime++) {
    if (prime * prime > remaining) prime = remaining;
    if (remaining % prime !== 0) continue;
    let needed = 0;
    while (remaining % prime === 0) {
      remaining /= prime;
      needed++;
    }
    let available = 0;
    for (const value of numbers) {
      let rest = value;
      while (rest % prime === 0) {
        rest /= prime;
        available++;
      }
    }
    answer = Math.min(answer, Math.floor(available / needed));
  }
  return answer;
}
